import{Q as Qa,_n as vc,pt as Xf,rt as UN,tn as qf}from"./chunk-w1yXPyTv.js";import{t as f}from"./chunk-kq7BNLTU.js";import{t as b}from"./chunk-DuzT0A3R.js";var c=class n{static ɵfac=function(o){return new(o||n)};static ɵcmp=qf({type:n,selectors:[[`mci-pastors`]],decls:70,vars:0,consts:[[`imageUrl`,`https://images.unsplash.com/photo-1603796846027-0e536de14fde?q=80&w=765&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D`,`title`,`Parroci`],[1,`height-container`],[`title`,`Padre Bruno Zuchowski`,`backgroundColor`,`var(--mat-sys-surface)`,`textColor`,`var(--mat-sys-on-surface)`],[1,`biography`,`current-pastor`],[`src`,`images/padre-bruno-zuchowski.jpg`,`alt`,`Padre Bruno Zuchowski`,`width`,`190`,`height`,`143`,`loading`,`lazy`,`decoding`,`async`],[`lang`,`de`],[`title`,`Essere "Cristiano" oggi`,`backgroundColor`,`var(--mat-sys-surface-container)`,`textColor`,`var(--mat-sys-on-surface)`],[1,`reflection`],[`title`,`Due pastori nella memoria della comunità`,`backgroundColor`,`var(--mat-sys-surface)`,`textColor`,`var(--mat-sys-on-surface)`],[1,`biography`],[`src`,`images/don-mario-fraschini-hd.jpg`,`alt`,`Ritratto di don Mario Fraschini`,`loading`,`lazy`,`decoding`,`async`],[`src`,`images/don-andrea-gozio-hd.png`,`alt`,`Ritratto di don Andrea Gozio`,`loading`,`lazy`,`decoding`,`async`]],template:function(o,m){o&1&&(vc(0,`mci-hero`,0),Qa(1,`div`,1)(2,`mci-section`,2)(3,`div`,3),vc(4,`img`,4),Qa(5,`p`),UN(6,`Padre Bruno Zuchowski è il nostro parroco e accompagna la comunità italiana di Augsburg nel suo cammino di fede. Sacerdote cattolico italiano, appartiene alla congregazione dei Padri dei Sacri Cuori (SSCC) e dedica da molti anni il suo servizio missionario agli italiani in Germania.`),Xf(),Qa(7,`p`),UN(8,`Rettore delle Missioni Cattoliche Italiane di Augsburg e Kempten, è vicino alla vita delle comunità e alla cura pastorale degli italiani all’estero. Nel maggio 2022 ha celebrato il suo 40° anniversario di sacerdozio: una tappa importante di un cammino che continua nel segno della fede e del servizio.`),Xf(),Qa(9,`p`),UN(10,`Il suo impegno di «Missionario degli Italiani» si intreccia anche con la vita associativa. Per sette anni ha ricoperto il ruolo di `),Qa(11,`span`,5),UN(12,`Präses`),Xf(),UN(13,` (presidente) della sezione locale della KAB, l’Azione Cattolica dei Lavoratori, nella parrocchia di Sankt Anton a Kempten. La sua guida spirituale e le sue profonde conoscenze bibliche sono un punto di riferimento per chi lo incontra.`),Xf()()(),Qa(14,`mci-section`,6)(15,`article`,7)(16,`p`),UN(17,`Essere Cristiani, seguaci di Cristo e della sua parola. Una parola d’amore che racchiude tutto uno stile di vita.`),Xf(),Qa(18,`p`),UN(19,`“Amatevi gli uni e gli altri come io ho amato voi”. Questo è quanto ci viene chiesto per essere cristiani. Se veramente vivessimo la nostra vita sull'impronta di Cristo non ci sarebbero tutte le cose brutte che succedono nel mondo perché l'amore per il nostro fratello ci impedirebbe di fargli del male. Sta a noi la scelta, il libero arbitrio dell'uomo.`),Xf(),Qa(20,`p`),UN(21,`Le strade da seguire sono parallele ma la loro direzione è opposta. Da una parte il bene, dall'altra il male, tutto dipende da noi. Lo svolgersi della nostra vita dipende da questa scelta.`),Xf(),Qa(22,`p`),UN(23,`Non possono esserci vie di mezzo, non possono esserci compromessi. Non si può seguire Dio e allo stesso tempo Mammona (termine ebraico che significa sicurezza economica che appaga e dà sicurezza).`),Xf(),Qa(24,`p`),UN(25,`Dobbiamo avere le idee chiare, pur sapendo che la strada dell'amore è più irta e piena di ostacoli. Il nostro piede rischierà di inciampare ma, Dio “ha dato ordine ai suoi angeli di custodirci in tutti i nostri passi”.`),Xf(),Qa(26,`p`),UN(27,`Nel tratto di strada più accidentato ci solleveranno da terra e ci porteranno in braccio.`),Xf(),Qa(28,`p`),UN(29,`Perché Dio così ha comandato di fare. Perché Dio nella sua infinita bontà non ci lascerà cadere mai. Non lascerà che ci venga tolto un solo capello. Affidiamoci con fede alla sua misericordia e gli effetti di questa stupenda amicizia non tarderanno a manifestarsi nella nostra vita.`),Xf(),Qa(30,`p`),UN(31,`Affidiamo a lui il nostro cuore e lasciamo che lo ricolmi di grazia e d’amore. Solo allora il mondo con le sue vanità, che tra l’altro sono destinate a sparire, ci sembrerà vuoto.`),Xf(),Qa(32,`p`),UN(33,`Lasciamo che il nostro spirito si elevi al di sopra della materialità di questa terra e raggiunga la “luce vera” che aspetta con infinita pazienza che noi ci ricordiamo di Lui.`),Xf(),Qa(34,`p`),UN(35,`Apriamo al Signore che bussa, rispondiamo a Lui come fece Maria “Eccomi sono la serva del Signore si compia di me secondo la tua parola”. Solo in questo modo un’immensa pace e tanta tranquillità sostituirà “l’ansia della vita”, e soprattutto l’attaccamento alle cose materiali.`),Xf(),Qa(36,`p`),UN(37,`E fiumi di grazie il Signore riverserà su di noi perché siamo suoi figli e il suo amore per noi non ha eguali.`),Xf(),Qa(38,`footer`)(39,`p`)(40,`strong`),UN(41,`Padre Bruno Zuchowski`),Xf(),vc(42,`br`),UN(43,`Missionario degli Italiani`),Xf()()()(),Qa(44,`mci-section`,8)(45,`article`,9)(46,`h3`),UN(47,`Don Mario Fraschini`),Xf(),vc(48,`img`,10),Qa(49,`p`),UN(50,`Nato a Pietra de’ Giorgi, in provincia di Pavia, don Mario Fraschini dedicò la propria vita agli emigrati italiani. Lasciò la diocesi di Tortona nel 1965 e operò per 28 anni nella diocesi di Augsburg, in Baviera.`),Xf(),Qa(51,`p`),UN(52,`Il doposcuola, la catechesi e gli incontri di formazione e amicizia furono tra i suoi impegni principali. La sua dedizione gli valse la stima della Chiesa locale. La rinnovata Domus Latina, messa a disposizione dalla diocesi in Alte Gasse, fu un riconoscimento del suo costante lavoro sociale e pastorale.`),Xf(),Qa(53,`p`),UN(54,`Vicino alla sua gente, cercò sempre anche la collaborazione con il clero locale. Per molti anni fu membro attivo del Consiglio presbiterale della diocesi di Augsburg, che lo onorò con il titolo di `),Qa(55,`em`,5),UN(56,`Geistlicher Rat`),Xf(),UN(57,`. Morì il 24 gennaio 2000 a Pietra de’ Giorgi.`),Xf()(),Qa(58,`article`,9)(59,`h3`),UN(60,`Don Andrea Gozio`),Xf(),vc(61,`img`,11),Qa(62,`p`),UN(63,`Don Andrea Gozio nacque il 3 gennaio 1943 a Gussago e fu ordinato sacerdote a Brescia il 31 agosto 1968. Nella sua diocesi fu vicario cooperatore prima a Provaglio d’Iseo, fino al 1974, e poi a Lumezzane, fino alla partenza per la Germania nel 1980.`),Xf(),Qa(64,`p`),UN(65,`Iniziò il suo servizio in Germania come vicario tra gli italiani di Offenbach, nella diocesi di Mainz. Due anni dopo divenne amministratore della Missione Cattolica Italiana. Dal 1° ottobre 1983 assunse la direzione della Missione di Braunschweig, nella diocesi di Hildesheim. Il 1° marzo 1993 fu nominato rettore della Missione di Augsburg, che continuò a guidare anche nei difficili mesi della malattia.`),Xf(),Qa(66,`p`),UN(67,`Fu per molti anni membro del Consiglio di Delegazione: dal giugno 1992 per la Lega Anseatica e dal settembre 1998 per la Baviera, fino all’anno precedente la sua morte. Curava in particolare la liturgia dei convegni e degli incontri e svolgeva con precisione e fedeltà gli incarichi ricevuti.`),Xf(),Qa(68,`p`),UN(69,`Padre Bassanelli lo ricordava per una dedizione ai connazionali che andava oltre l’ambito strettamente religioso e pastorale, mettendosi al servizio di ogni persona nella sua situazione concreta. Don Andrea morì il 15 maggio 2012 a Gussano, in provincia di Brescia, come riportato nella biografia originale.`),Xf()()()())},dependencies:[b,f],styles:[`[_nghost-%COMP%]   h3[_ngcontent-%COMP%]{margin-block:48px 24px;font-size:clamp(1.625rem,1rem + 2vw,2.375rem)}[_nghost-%COMP%]   .biography[_ngcontent-%COMP%]{display:flow-root}[_nghost-%COMP%]   .biography[_ngcontent-%COMP%]   img[_ngcontent-%COMP%]{float:inline-start;width:220px;max-width:100%;height:auto;margin:8px 24px 8px 0;border-radius:30px}[_nghost-%COMP%]   .current-pastor[_ngcontent-%COMP%]{margin-block-start:32px}[_nghost-%COMP%]   .current-pastor[_ngcontent-%COMP%]   img[_ngcontent-%COMP%]{width:190px;border-radius:20px}[_nghost-%COMP%]   .reflection[_ngcontent-%COMP%]   p[_ngcontent-%COMP%] + p[_ngcontent-%COMP%]{margin-block-start:1.5em}[_nghost-%COMP%]   .reflection[_ngcontent-%COMP%]   footer[_ngcontent-%COMP%]{margin-block-start:48px}[_nghost-%COMP%]   .source-note[_ngcontent-%COMP%]{font-size:1rem}[_nghost-%COMP%]   .source-note[_ngcontent-%COMP%]   a[_ngcontent-%COMP%]{color:inherit;text-underline-offset:3px}[_nghost-%COMP%]   .source-note[_ngcontent-%COMP%]   a[_ngcontent-%COMP%]:focus-visible{outline:2px solid currentColor;outline-offset:4px}@media(max-width:700px){[_nghost-%COMP%]   .biography[_ngcontent-%COMP%]   img[_ngcontent-%COMP%]{float:none;display:block;margin-bottom:24px}}`]})};export{c as PastorsComponent};